config.transformExpression:
// filter
let filter = '';
if (event.metadata.hasOwnProperty('filter')) 
{
    filter = event.metadata.filter;
}
stage.setMetadata("filter", filter);

//level
let level = 0;
if (event.metadata.hasOwnProperty('level')) 
{
    level = event.metadata.level;
}
stage.setMetadata("level", level);

// expression
let expression = "$keys(event.value.data.$)";
if (level > 0)
{
    expression = "$keys(event.value.data." + filter + "$)";
}
stage.setMetadata("expression", expression);

// index
let index = 0;
if (event.metadata.hasOwnProperty('index')) 
{
    index = event.metadata.index;
}
stage.setMetadata("index", index);

// previousIndexes
let previousIndexes = [0];
if (event.metadata.hasOwnProperty('previousIndexes')) 
{
    previousIndexes = event.metadata.previousIndexes;
}
stage.setMetadata("previousIndexes", previousIndexes);

// parentNamespaceIds
let parentNamespaceIds = [''];
if (event.metadata.hasOwnProperty('parentNamespaceIds')) 
{
    parentNamespaceIds = event.metadata.parentNamespaceIds;
}
stage.setMetadata("parentNamespaceIds", parentNamespaceIds);
stage.setMetadata("parentNamespaceId", parentNamespaceIds[level]);

// writeNamespaces
stage.setMetadata("writeNamespaces", false);

stage.setValue(event.value);

// level
let level = event.metadata.level + 1;
stage.setMetadata("level", level);

// previousIndexes
if ((event.metadata.previousIndexes.length -1) < level)
{
    let previousIndexes = event.metadata.previousIndexes.toSpliced(level, 0, 0)
    stage.setMetadata("previousIndexes", previousIndexes);
}
else
{
    let previousIndexes = event.metadata.previousIndexes;
    previousIndexes[level] = 0;
    stage.setMetadata("previousIndexes", previousIndexes);
}

// filter
if (event.metadata.filter != '')
{
    stage.setMetadata("filter", event.metadata.filter + event.value + ".");
}
else
{
    stage.setMetadata("filter", event.value + ".");
}
stage.setMetadata("index", 0);

// currnet id
stage.setMetadata("id", event.id);

// parentNamespaceIds
if ((event.metadata.parentNamespaceIds.length -1) < level)
{
    let parentNamespaceIds = event.metadata.parentNamespaceIds.toSpliced(level, 0, event.id)
    stage.setMetadata("parentNamespaceIds", parentNamespaceIds);
}
else
{
    let parentNamespaceIds = event.metadata.parentNamespaceIds;
    parentNamespaceIds[level] = event.id;
    stage.setMetadata("parentNamespaceIds", parentNamespaceIds);
}

stage.setValue(event.value);

expression.expression:
const path = event.metadata.filter;
const result = path.slice(0, -1).replaceAll('.', '/');
return result;

config.transformExpression:
// update level
let level = event.metadata.level - 1;
stage.setMetadata("level", level);

// update filter
let filterArr = event.metadata.filter.split(".");
let currentFilter = filterArr[level] + ".";
let filter = event.metadata.filter.replace(currentFilter, '');
stage.setMetadata("filter", filter);

// update previousIndexes
let previousIndexes = event.metadata.previousIndexes;
let index = previousIndexes[level] + 1;
stage.setMetadata("index", index);
previousIndexes[level] = index;
stage.setMetadata("previousIndexes", previousIndexes);

stage.setValue(event.value);
